/*
 * Tests de parité : moteur public/moteurs/credit/credit.js
 * contre le simulateur d'origine public/outils/credit/js/app.js.
 *
 * Les valeurs attendues ont été produites en exécutant les fonctions
 * d'origine (calculerEcheancier, calculerTEG, agregerAnnuel, valeurActuelle,
 * simulerStress, lienSimulation, lireLienPartage et les calculs des outils
 * Capacité, Calcul inverse, Plan de financement, Comparer des offres,
 * Renégociation, Louer ou acheter, Quand demander la réduction), extraites
 * telles quelles de app.js dans un bac à sable node:vm (DOM simulé), puis
 * recopiées ci-dessous. Tolérance : le millime (0,0005) pour les montants.
 */
"use strict";

const test = require("node:test");
const assert = require("node:assert/strict");
const M = require("../../public/moteurs/credit/credit.js");

const TOL = 0.0005;
function proche(reel, attendu, msg, tol = TOL) {
  if (attendu === null || attendu === undefined) { assert.equal(reel, attendu, msg); return; }
  if (typeof attendu === "number" && !isFinite(attendu)) { assert.ok(Object.is(reel, attendu) || (isNaN(reel) && isNaN(attendu)), msg + " : " + reel); return; }
  assert.ok(typeof reel === "number" && Math.abs(reel - attendu) <= tol, `${msg} : obtenu ${reel}, attendu ${attendu}`);
}
function suite(reel, attendu, msg, tol = TOL) {
  assert.equal(reel.length, attendu.length, `${msg} : ${reel.length} valeurs au lieu de ${attendu.length} (${JSON.stringify(reel)})`);
  attendu.forEach((v, i) => proche(reel[i], v, `${msg} [${i}]`, tol));
}
const r3 = v => Math.round(v * 1000) / 1000;
function sansNull(o) {
  if (Array.isArray(o)) return o.map(sansNull);
  if (o && typeof o === "object") { const r = {}; Object.keys(o).forEach(k => { if (o[k] !== null && o[k] !== undefined) r[k] = sansNull(o[k]); }); return r; }
  return o;
}

