ECHEANCIERS.forEach((s) => {
  test("parité échéancier : " + s.nom, () => {
    const r = M.echeancier(JSON.parse(JSON.stringify(s.entree)), s.reduire);
    const a = s.attendu;
    ["M1", "M2", "ta2", "totI", "totP", "totM", "totIndem", "totAss", "totRA", "frais", "coutTotal", "coutCredit", "tm"].forEach((k) => proche(r[k], a[k], k, k === "ta2" ? 1e-8 : TOL));
    ["n", "nPrevu", "D", "reduc", "reducDemandee"].forEach((k) => assert.equal(r[k], a[k], k));
    proche(r.teg, a.teg, "TEG", 1e-6);
    assert.equal(r.paliers.length, a.paliers.length, "nombre de paliers");
    a.paliers.forEach((p, i) => { assert.equal(r.paliers[i].mois, p.mois, "palier " + i); proche(r.paliers[i].M, p.M, "palier M " + i); proche(r.paliers[i].taux, p.taux, "palier taux " + i, 1e-8); });
    assert.equal(r.reductions.length, a.reductions.length, "nombre de réductions de taux");
    a.reductions.forEach((z, i) => {
      const y = r.reductions[i];
      assert.equal(y.mois, z.mois, "réduction " + i + " : échéance");
      proche(y.avant, z.avant, "réduction avant", 1e-8); proche(y.apres, z.apres, "réduction après", 1e-8);
      proche(y.ratio, z.ratio, "réduction ratio", 1e-8); proche(y.interets, z.interets, "réduction intérêts 36 mois");
      proche(y.reste, z.reste, "réduction CRD"); proche(y.M, z.M, "réduction nouvelle échéance");
    });
    assert.equal(r.ras.length, a.ras.length, "remboursements anticipés");
    a.ras.forEach((z, i) => { assert.equal(r.ras[i].mois, z.mois); proche(r.ras[i].montant, z.montant, "RA montant"); proche(r.ras[i].indemnite, z.indemnite, "RA indemnité"); assert.equal(r.ras[i].limite, z.limite); });
    ["paiement", "interet", "principal", "assurance"].forEach((k) => proche(r3(r.lignes.reduce((t, l) => t + l[k], 0)), a.sommes[k], "somme " + k));
    a.lignes.forEach((x) => {
      const l = r.lignes[x.mois - 1];
      assert.ok(l, "ligne " + x.mois);
      ["paiement", "interet", "principal", "assurance", "reste"].forEach((k) => proche(l[k], x[k], "ligne " + x.mois + " " + k));
      ["reduit", "reduction", "revise", "differe"].forEach((k) => assert.equal(l[k], x[k], "ligne " + x.mois + " " + k));
      if (x.date) assert.deepEqual([l.date.getFullYear(), l.date.getMonth() + 1, l.date.getDate()], x.date, "date ligne " + x.mois);
      else assert.equal(l.date, null);
      if (x.ra) { proche(l.ra.montant, x.ra.montant, "RA ligne"); proche(l.ra.indemnite, x.ra.indemnite, "RA indemnité"); proche(l.ra.reste, x.ra.reste, "RA reste"); assert.equal(l.ra.limite, x.ra.limite); }
      else assert.equal(l.ra, undefined);
      if (x.ratio !== undefined) proche(l.ratio, x.ratio, "ratio 8 % ligne " + x.mois, 1e-8);
      if (x.int36 !== undefined) proche(l.int36, x.int36, "intérêts 36 mois ligne " + x.mois);
    });
    const an = M.agregerAnnuel(r), anA = a.annuel;
    an.filter((x, i, t) => i < 2 || i === t.length - 1).forEach((y, i) => {
      const z = anA[i];
      ["paiement", "interet", "principal", "assurance", "reste"].forEach((k) => proche(y[k], z[k], "année " + z.annee + " " + k));
      assert.equal(y.annee, z.annee); assert.equal(y.nb, z.nb);
    });
    proche(M.valeurActuelle(r, 5), a.valeurActuelle5, "valeur actuelle à 5 %");
  });
});

test("parité : déclenchement de la réduction de moitié du taux (règle des 84 mois / 8 %)", () => {
  const trouve = (nom) => ECHEANCIERS.find((s) => s.nom.startsWith(nom));
  const a = M.echeancier(trouve("immobilier 250 000").entree, true);
  assert.deepEqual(a.reductions.map((z) => z.mois), [37, 73, 139, 286], "1er test à l'échéance 37, puis 36 mois après chaque réduction");
  assert.ok(a.lignes[35].test.ok && a.lignes[35].test.ratio > 0.08, "test porté par la ligne 36 (avant l'échéance 37)");
  const b = M.echeancier(trouve("taux bas 2,5 %").entree, true);
  assert.equal(b.reductions[0].mois, 87, "ratio sous 8 % à l'échéance 37 : nouveau test chaque mois (fenêtre glissante)");
  assert.ok(b.lignes[84].test.ok === false && b.lignes[85].test.ok === true);
  assert.equal(M.echeancier(trouve("règle des 84 mois").entree, true).reducDemandee, false, "84 mois : pas de réduction");
  const t = M.echeancier(trouve("trimestriel 180 mois").entree, true);
  assert.equal(t.reductions[0].mois, 13, "trimestriel : fenêtre de 12 échéances");
});

