    const r = M.capaciteEmprunt({ revenuNet: c.entree.rev, charges: c.entree.ch, dureeMois: c.entree.dur, tauxAnnuelPct: c.entree.taux });
    if (c.attendu.nul) { assert.equal(r.motif, "charges-trop-elevees"); assert.equal(r.capital, 0); return; }
    proche(r.capaciteEndettement, c.attendu.capaciteEndettement, "capacité d'endettement");
