const INVERSE = [
  {"entree":{"mode":"capital","M":1200,"n":180,"t":8.5},"html":"Coût des intérêts [[94140.34]] Capital empruntable [[121859.66]]","argent":[94140.34,121859.66],"taux":[],"mois":[],"applique":{"capital":121859.66,"mois":180,"taux":8.5}},
  {"entree":{"mode":"capital","M":500,"n":48,"t":0},"html":"Coût des intérêts [[0]] Capital empruntable [[24000]]","argent":[0,24000],"taux":[],"mois":[],"applique":{"capital":24000,"mois":48,"taux":0}},
  {"entree":{"mode":"duree","M":1500,"C":100000,"t":9},"html":"Mensualité sur cette durée [[1497.382]] Durée nécessaire > (7.8 ans)","argent":[1497.382],"taux":[],"mois":[93],"applique":{"capital":100000,"mois":93,"taux":9}},
  {"entree":{"mode":"duree","M":500,"C":100000,"t":9},"html":"Cette mensualité ne couvre pas les intérêts du premier mois ([[750]]) : le crédit ne serait jamais remboursé.","argent":[750],"taux":[],"mois":[],"applique":null},
  {"entree":{"mode":"duree","M":400,"C":100000,"t":2},"html":"Il faudrait plus de 300 mois : augmentez la mensualité.","argent":[],"taux":[],"mois":[],"applique":null},
  {"entree":{"mode":"taux","M":1100,"C":100000,"n":120},"html":"Mensualité à ce taux [[1099.988]] Taux annuel maximal {{5.796}}","argent":[1099.988],"taux":[5.796],"mois":[],"applique":{"capital":100000,"mois":120,"taux":5.796}},
  {"entree":{"mode":"taux","M":800,"C":100000,"n":120},"html":"La mensualité est trop faible pour rembourser le capital sur cette durée, même sans intérêts.","argent":[],"taux":[],"mois":[],"applique":null}
];
INVERSE.forEach((c) => {
  const e = c.entree;
  test(`parité calcul inverse (${e.mode}) : ${c.html.slice(0, 60)}`, () => {
    const r = M.calculInverse({ mode: e.mode, mensualite: e.M, capital: e.C, mois: e.n, taux: e.t });
    if (/ne couvre pas/.test(c.html)) { assert.equal(r.erreur, "interets-non-couverts"); proche(r.interetsPremierMois, c.argent[0], "intérêts du 1er mois"); return; }
    if (/plus de 300/.test(c.html)) { assert.equal(r.erreur, "plus-de-300-mois"); return; }
    if (/trop faible/.test(c.html)) { assert.equal(r.erreur, "mensualite-trop-faible"); return; }
    if (e.mode === "capital") { suite([r.interets, r.capital], c.argent, "intérêts et capital"); }
    else if (e.mode === "duree") { suite([r.mensualiteReelle], c.argent, "mensualité réelle"); assert.equal(r.mois, c.mois[0]); }
    else { suite([r.mensualiteReelle], c.argent, "mensualité réelle"); proche(r.taux, c.taux[0], "taux"); }
    assert.deepEqual({ capital: r.capital, mois: r.mois, taux: r.taux }, c.applique);
  });
});

